{"command":"cd /testbed/security-signoff && python3 - <<'EOF'
import json, yaml
scan = json.load(open("release/RC-17/scan.json"))
pol = yaml.safe_load(open("policy/scan_scope.yaml"))
official = pol["components"]
th = pol["thresholds"]
default_max = th["default"].get("findings_max")
comp_limits = th.get("components", {})
by = {c["component"]: c for c in scan["components"]}
not_clean = []
print(f"policy snapshot={pol.get('snapshot')} scope={pol.get('scope')} scan snapshot={scan.get('snapshot')} ruleset={scan.get('ruleset_version')}")
print(f"official={official} default findings_max={default_max} per-component limits={comp_limits}")
for name in official:
    c = by.get(name)
    reasons = []
    if c is None:
        reasons.append("missing from captured scan")
    else:
        if c.get("scan_status") != "complete":
            reasons.append(f"scan_status={c.get('scan_status')}")
        f = c.get("findings")
        if not isinstance(f, (int, float)):
            reasons.append("no finding count")
        elif f > default_max:
            reasons.append(f"findings={f} > default max {default_max}")
        lim = comp_limits.get(name) or {}
        if "exposure_score_max" in lim:
            es = c.get("exposure_score")
            if es is None:
                reasons.append("exposure limit set but no exposure_score captured")
            elif es > lim["exposure_score_max"]:
                reasons.append(f"exposure_score={es} > limit {lim['exposure_score_max']}")
        extra = set(lim) - {"exposure_score_max"}
        if extra: reasons.append(f"unhandled limits: {extra}")
    status = "NOT CLEAN" if reasons else "clean"
    print(f"  {name:18s} {status:9s} {'; '.join(reasons)}")
    if reasons: not_clean.append(name)
print("NOT CLEAN:", not_clean)
print("conclusion:", "not-clean" if not_clean else "clean")
# scope coverage check
missing = [n for n in official if n not in by]
extra_in_scan = [n for n in by if n not in official]
print("scope coverage: missing from scan =", missing, "| in scan but not official =", extra_in_scan)
EOF"}
